mapper.select:
SELECT result_payload
FROM evacuation_route_store
WHERE cache_key = #{cacheKey}

mapper.delete:
DELETE FROM evacuation_route_store
WHERE layout_version_id = #{layoutVersionId}
  AND cache_key != #{cacheKey}

DELETE FROM evacuation_route_store
WHERE computed_at < (
    SELECT boundary.computed_at
    FROM (
        SELECT computed_at
        FROM evacuation_route_store
        ORDER BY computed_at DESC
        LIMIT 1 OFFSET #{limit}
    ) boundary
)
